import { appendSplitCsv, copySplitFile, ensureSplitFolder, splitPath } from "~/core/persistence/splitFiles";

/**
 * gen5's `logData`, `logCopy`, `transition` and `loadCsvFile` (the helpers above its
 * component in `frontend.js`), on the splits IPC instead of `require("fs")` (plan
 * 2.4 / 1.6). Generated by tools/port/lift-gen5.py, so the header string and path
 * segments are byte-for-byte gen5's. Since 2026-10-14 only the simple CSV is written,
 * named `<Species>-<N>.csv` (no `-simple`). It keeps the test-run quirk shared with
 * gen4 (`testStatus` moves the folder to `test_runs/` but the file name is the normal
 * one), and gen5's own `logCopy`,
 * which follows `refilming_mode` and nests `finishes/` under the refilmed path
 * (known-legacy-bugs.md #21).
 *
 * The legacy file also created `splits/`, `splits/Platinum` and `splits/HGSS` when
 * it loaded -- gen4 leftovers it never writes to (known-legacy-bugs.md #17) --
 * which is reproduced below.
 */
for (const folder of ['', 'Platinum', 'HGSS']) {
    void ensureSplitFolder(folder);
}

export function logData(gameName, str, file_name, split_file_prefix, testStatus, evolution, evolution_label, refilming_mode) {
        // When evolution is enabled, use the evolution_label which should be in "FullyEvolved-line" format
        // Otherwise, use split_file_prefix which is the species name
        if (evolution == true && evolution_label) {
            split_file_prefix = evolution_label;
        }
        // File paths
        var dirPath  = refilming_mode == true ? splitPath(gameName, "refilmed", split_file_prefix) : splitPath(gameName, split_file_prefix);
        if (testStatus == true) { 
            dirPath = splitPath(gameName, split_file_prefix, "test_runs"); 
        }
        const filePath = splitPath(dirPath, `${split_file_prefix}-${file_name}.csv`);
        // Header
        const header = "player_name," + "pokemon," + "trainer_name," + "real_time_hmmss," + "resets," + "blackouts," + "level," + "game_time," + "battle_duration," + "move1," + "move2," + "move3," + "move4,\n"
        return appendSplitCsv(filePath, header, str);
}

export function logCopy(gameName, file_name, splitFileName, finished_run_count, refilming_mode) {
    // Copy this run's attempt file into finishes/. logData writes attempts under
    // refilmed/ when refilming mode is on, so source and destination follow it there.
    var dirPathAttempts = refilming_mode == true ? splitPath(gameName, "refilmed", splitFileName) : splitPath(gameName, splitFileName);
    var dirPathFinishes = splitPath(dirPathAttempts, "finishes");
    return copySplitFile(
        splitPath(dirPathAttempts, `${splitFileName}-${file_name}.csv`),
        splitPath(dirPathFinishes, `${splitFileName}-${finished_run_count}.csv`));
}

export function transition(fn, ms) {
    return new Promise((resolve) => {
        const T = performance.now()
        function step() {
            const t = performance.now() - T
            fn(Math.min(t / ms, 1))
            if (t < ms) requestAnimationFrame(step)
            else resolve()
        }
        requestAnimationFrame(step)
    })
}

/** The file picker behind "Load Splits": the File System Access API is Chromium's, not Node's. */
export async function loadCsvFile() {
    const file = await window.showOpenFilePicker({
        id: "SplitsFolder",
        types: [{
            description: "Split files",
            accept: { "text/csv": [".csv"] }
        }]
    });
    const contents = await file[0].getFile();
    const text = await contents.text();
    return text;
}
